//! Compare two-slot projection with retained original-instruction output.
use spore_core::cell_pool_two_slot_v1::Pool;
fn w(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn main(){let path=std::env::args().nth(1).expect("native stdout");let b=std::fs::read(path).unwrap();assert_eq!(b.len(),88);let mut p=Pool::new(true).unwrap();let a=p.allocate().unwrap().unwrap();let d=p.allocate().unwrap().unwrap();let full=p.allocate().unwrap().unwrap_or(0);let h0=u32::from_le_bytes(p.slots[0][..4].try_into().unwrap());let h1=u32::from_le_bytes(p.slots[1][..4].try_into().unwrap());assert!(p.slots.iter().all(|x|x[4..].iter().all(|&x|x==0)));let mut c=0;let i0=p.iterate_offset(&mut c).unwrap().unwrap() as u32;let i1=p.iterate_offset(&mut c).unwrap().unwrap() as u32;let end=p.iterate_offset(&mut c).unwrap().map(|x|x as u32).unwrap_or(0);let endcur=c;p.slots[0][..4].copy_from_slice(&u32::MAX.to_le_bytes());c=0;let skip=p.iterate_offset(&mut c).unwrap().unwrap() as u32;let skipcur=c;let end2=p.iterate_offset(&mut c).unwrap().map(|x|x as u32).unwrap_or(0);let got=[a,d,full,h0,h1,p.lookup_offset(a).unwrap() as u32,p.lookup_offset(d).unwrap() as u32,i0,i1,end,endcur,skip,skipcur,end2,c,2,p.count,p.high_water,p.generation];let want:Vec<_>=(0..19).map(|j|w(&b,j*4)).collect();assert_eq!(got.as_slice(),want);let fp=w(&b,76);assert_eq!(fp&0xffff,0x27f);assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(&b,80)&!0x3f,0x1f80);println!("matched retained two-slot fresh allocation and iteration; no scheduler observed");}
